  \    \"defs\": {\n\
  \        \"decorator\": {\n\
  \            \"type\": \"object\",\n\
  \            \"properties\": {\n\
  \                \"unique-id\": {\n\
  \                    \"type\": \"string\",\n\
  \                    \"description\": \"Unique identifier for this decorator\"\n\
  \                },\n\
  \                \"type\": {\n\
  \                    \"type\": \"string\",\n\
  \                    \"description\": \"Type of decorator - a free-form string identifying the decorator category\"\n\
  \                },\n\
  \                \"target\": {\n\
  \                    \"type\": \"array\",\n\
  \                    \"items\": {\n\
  \                        \"type\": \"string\"\n\
  \                    },\n\
  \                    \"minItems\": 1,\n\
  \                    \"description\": \"Array of file paths or URLs referencing the CALM documents (patterns, architectures, or controls) this decorator targets\"\n\
  \                },\n\
  \                \"applies-to\": {\n\
  \                    \"type\": \"array\",\n\
  \                    \"items\": {\n\
  \                        \"type\": \"string\"\n\
  \                    },\n\
  \                    \"minItems\": 1,\n\
  \                    \"description\": \"Array of unique-ids referencing nodes, relationships, flows, or other architecture elements\"\n\
  \                },\n\
  \                \"data\": {\n\
  \                    \"type\": \"object\",\n\
  \                    \"minProperties\": 1,\n\
  \                    \"description\": \"Free-form JSON object containing the decorator's data\"\n\
  \                }\n\
  \            },\n\
  \            \"required\": [\n\
  \                \"unique-id\",\n\
  \                \"type\",\n\
  \                \"target\",\n\
  \                \"applies-to\",\n\
  \                \"data\"\n\
  \            ],\n\
  \            \"additionalProperties\": false\n\
  \        }\n\
  \    }\n\
  \}"
